import { supabase } from './client'
import type { Fund } from '@/entities/fund/types'

export const fundsService = {
  async listFunds(projectId: string): Promise<Fund[]> {
    const { data, error } = await supabase.from('funds').select('*').eq('project_id', projectId)
    if (error) throw error
    return (data ?? []) as Fund[]
  },
}
